function parseLogLine(line) {
  const m = line.match(/^(?<date>\d{4}-\d{2}-\d{2}) (?<time>\d{2}:\d{2}:\d{2}) \[(?<level>[A-Z]+)\] (?<source>\w+): (?<message>.+)$/)
  return m ? { ...m.groups } : null
}

